{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "We included randomized controlled trials (RCT) and cluster RCTs designed to evaluate the efficacy of opioids prescribed for relief of acute pain in ED-­ discharged patients compared to nonopioid analgesics. All types of pain complaints were considered. We excluded studies exclusively on patients with substance use disorder or chronic pain, evaluating only opioids given during the ED stay, comparing different opioids head-­ to-­ head, not reporting pain intensities or pain relief (after contacting authors), or available only as abstracts.",
      "reason": "The eligibility criteria specify study designs (RCTs, cluster RCTs), setting (ED-discharged patients), interventions/comparators, populations included and excluded, and outcomes of interest. However, no explicit follow-up requirements or other question-framework components (e.g., minimum follow-up duration) are specified, so the element is only partially met."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "We excluded studies ... available only as abstracts. There were no exclusions based on language or date of publication.",
      "reason": "The report specifies publication/report status (excludes abstracts), language and date criteria (no exclusions based on language or date), fulfilling the requirement for report characteristic eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "We excluded studies ... not reporting pain intensities or pain relief (after contacting authors)...",
      "reason": "Although the authors state they excluded studies not reporting pain intensities or pain relief after contacting authors, the report does not explicitly distinguish exclusions because outcomes were not measured versus outcomes were measured but not reported; no clear differentiation is provided."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "If data were available for at least three studies, results for the main outcome and for adverse events were pooled and meta-­ analyzed. For the main efficacy outcome, studies that reported mean and standard deviation (SD) of pain relief for both opioid and nonopioid groups were expressed by standard mean differences (SMD) in forest plots. ... Sensitivity analyses were performed for studies with available short-­ term follow-­ up (≤3 days) ... Another sensitivity analysis compared patients treated with codeine versus those treated with other opioids ... Sensitivity analyses were also performed excluding studies with high risk of bias and for studies involving a pediatric population compared to adults. Finally, we repeated the same analyses while excluding studies for which the comparator was only a placebo.",
      "reason": "The manuscript specifies the groups/comparisons used in syntheses (opioid vs nonopioid), how data were pooled, and a set of sensitivity analyses that link specified groups (e.g., codeine vs other opioids, pediatric vs adult, excluding placebo comparators) to the review comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "One of them 36 was further removed since it used dextropropoxyphene, an opioid that has been withdrawn from the market in 2009 because of its association with lethal events.",
      "reason": "A rationale is provided for exclusion of a study using a withdrawn opioid (safety/withdrawal reason). However, broader notable restrictions (e.g., excluding abstracts, excluding studies of opioids given only during ED stay, excluding chronic pain/substance use disorder populations) are listed without explicit rationales, so this requirement is only partially satisfied."
    }
  ],
  "confidence": 85
}

